css:
body {
	margin: 0;
	font-family: sans-serif;
}

.size.mk-3meddi {
				min-height: 48px;
				padding: 12px 16px;
				border: 2px solid #3d405b;
				border-radius: 12px;
				background: #ffffff;
				color: #3d405b;
				font-family: inherit;
				font-size: 18px;
				text-align: left;
			}
			.size[aria-pressed='true'].mk-3meddi {
				border-color: #e07a5f;
				font-weight: 700;
			}
.page.mk-zwsom1 {
				padding: 24px;
				background: #f4f1de;
				color: #3d405b;
			}
			.title.mk-zwsom1 {
				font-size: 26px;
				font-weight: 700;
			}
			.open.mk-zwsom1 {
				display: block;
				margin-top: 16px;
				padding: 12px 20px;
				border: 2px solid #3d405b;
				border-radius: 12px;
				background: #ffffff;
				color: #3d405b;
				font-family: inherit;
				font-size: 18px;
			}
			.sheet.mk-zwsom1 {
				padding: 24px;
			}
			.sizes.mk-zwsom1 {
				display: grid;
				gap: 8px;
			}
			.sheet-title.mk-zwsom1 {
				margin: 0 0 12px;
				font-size: 20px;
			}
